+import { spawnSync } from 'node:child_process';
 import { greet } from '../bin/greet.mjs';

+const command = new URL('../bin/greet.mjs', import.meta.url);
+
+function run(...args) {
+  return spawnSync(process.execPath, [command.pathname, ...args], { encoding: 'utf8' });
+}
