@@ -9,3 +16,54 @@ test('greets the world by default', () => {
 test('greets a name', () => {
   assert.equal(greet('Mike'), 'Hello, Mike!');
 });
+
+test('prints one greeting by default', () => {
+  const unnamed = run();
+  assert.equal(unnamed.status, 0);
+  assert.equal(unnamed.stdout, 'Hello, world!\n');
+  const named = run('Mike');
+  assert.equal(named.status, 0);
+  assert.equal(named.stdout, 'Hello, Mike!\n');
+});
+
+test('repeats greetings with the name before or after --times', () => {
+  for (const args of [['Mike', '--times', '3'], ['--times', '3', 'Mike']]) {
+    const result = run(...args);
+    assert.equal(result.status, 0);
+    assert.equal(result.stdout, 'Hello, Mike!\n'.repeat(3));
+    assert.equal(result.stderr, '');
+  }
+
+  const unnamed = run('--times', '3');
+  assert.equal(unnamed.status, 0);
+  assert.equal(unnamed.stdout, 'Hello, world!\n'.repeat(3));
+});
+
+test('rejects invalid --times values before printing', () => {
+  for (const args of [
+    ['--times', '0'],
+    ['--times', '-2'],
+    ['--times', '1.5'],
+    ['--times'],
+    ['--times', 'abc'],
+    ['--times', '9007199254740992'],
+  ]) {
+    const result = run(...args);
+    assert.notEqual(result.status, 0, args.join(' '));
+    assert.equal(result.stdout, '', args.join(' '));
+    assert.match(result.stderr, /--times requires a positive whole number/, args.join(' '));
+  }
+});
+
+test('rejects extra, duplicate, and unknown arguments before printing', () => {
